# Close a period (open or soft-closed): fix its due-total as it is now. A closed period cannot be closed again.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: close
close:
  class: net.officefloor.hq.app.period.ClosePeriod
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
# Reopen a closed period (a steward only): its due-total is live again.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: reopen
reopen:
  class: net.officefloor.hq.app.period.ReopenPeriod
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
# Soft-close a period: fix its due-total as it is now, while claims dated in it can still be changed.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: softClose
softClose:
  class: net.officefloor.hq.app.period.SoftClosePeriod
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
